+//! The thread mill's way in (#992): a thread mill is not centre-cutting,
+//! and the thread ride feeds it down the hole's axis and out along its
+//! lead-in arc. That is air only when an earlier operation opened the
+//! hole, so each threaded hole is read in the stock the program ahead
+//! leaves standing (the prior grid the drilling laws read,
+//! [`super::drill_prior`]) and a hole not open to the thread's depth is
+//! refused by name - never a thread mill fed into solid metal.
+//!
+//! Provenance: public machine-tool handbook thread milling (the tap-drill
+//! hole is made first, to the minor diameter, deeper than the thread);
+//! the prior-grid reading is our own design. No vendor material consulted.
+
+use crate::cl::Toolpath;
+use crate::drilling::Hole;
+use crate::machining2d::GenError;
+use crate::stock_sim::{Columns, Dexel};
+
+/// Float slack on the grid's stored heights, mm: a column cut exactly to
+/// the thread mill's lowest point is air there.
+const Z_SLACK: f64 = 1e-6;
+
+/// The lowest point the path takes the tool to inside `hole` (its moves
+/// whose ends stand within the hole's minor circle - every thread move
+/// does, the door keeps the mill inside it), or `None` when the path
+/// never enters the hole.
+fn lowest_in(path: &Toolpath, hole: &Hole) -> Option<f64> {
+    let inside = |p: crate::geometry::Point3| (p.x - hole.xy.x).hypot(p.y - hole.xy.y) <= hole.radius + 1e-6;
+    path.moves
+        .iter()
+        .flat_map(|m| [m.from, m.to])
+        .filter(|p| inside(*p))
+        .map(|p| p.z)
+        .fold(None, |lo: Option<f64>, z| Some(lo.map_or(z, |l| l.min(z))))
+}
+
+/// Why the program ahead has not opened every threaded hole, by name, or
+/// `Ok` when each is air under the thread mill. `prior` is the grid the
+/// setup's earlier operations leave standing; `None` (nothing ahead cut,
+/// or what is ahead cannot be read, or a posed frame no column grid
+/// reads) is unknown, which is refused - an unjudged hole is never air.
+///
+/// The disk read is the hole's minor circle less one grid cell (the
+/// lattice's own resolution: a drill of exactly the minor diameter cuts
+/// every column whose centre falls inside it), never narrower than the
+/// mill itself, from the stock top down to the mill's lowest point.
+pub(super) fn judge(holes: &[Hole], path: &Toolpath, tool_r: f64, prior: Option<&Dexel>) -> Result<(), GenError> {
+    for hole in holes {
+        let Some(low) = lowest_in(path, hole) else {
+            continue;
+        };
+        let (x, y, d) = (hole.xy.x, hole.xy.y, hole.radius * 2.0);
+        let advice = format!(
+            "a thread mill does not cut at its centre - add a drilling operation of at least the {d:.3} mm minor diameter, deep enough for its point, before the thread"
+        );
+        let Some(dex) = prior else {
+            return Err(GenError::Invalid(format!(
+                "the hole at ({x:.3}, {y:.3}) is not drilled yet: nothing ahead of the thread in this setup's program opens it, or the program ahead cannot be read - {advice}"
+            )));
+        };
+        let r = tool_r.max(hole.radius - dex.cell);
+        let top = if r.is_finite() && r >= 0.0 {
+            crate::verify::prior_surface(&Columns::of_grid(dex), hole.xy, r)
+        } else {
+            None
+        };
+        match top {
+            Some(top) if top <= low + Z_SLACK => {}
+            Some(top) => {
+                return Err(GenError::Invalid(format!(
+                    "the hole at ({x:.3}, {y:.3}) is not drilled yet: the stock the program ahead leaves stands at z {top:.3} inside it, above the thread mill's lowest point at z {low:.3} - {advice}"
+                )));
+            }
+            None => {
+                return Err(GenError::Invalid(format!(
+                    "the hole at ({x:.3}, {y:.3}) cannot be judged: the stock the program ahead leaves is unreadable there - {advice}"
+                )));
+            }
+        }
+    }
+    Ok(())
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use crate::cl::{Move, MoveKind};
+    use crate::geo2d::Point2;
+    use crate::geometry::Point3;
+
+    fn hole() -> Hole {
+        Hole { xy: Point2::new(0.0, 0.0), radius: 3.3, entry_z: 20.0, floor_z: 8.0, through: false, stepped: false }
+    }
+
+    /// A plunge down the axis to z 8 and a step out to the wall.
+    fn path() -> Toolpath {
+        let mv = |from: Point3, to: Point3| Move::new(MoveKind::Feed, from, to, Some(100.0));
+        let mut t = Toolpath::default();
+        t.moves.push(mv(Point3::new(0.0, 0.0, 25.0), Point3::new(0.0, 0.0, 8.0)));
+        t.moves.push(mv(Point3::new(0.0, 0.0, 8.0), Point3::new(0.3, 0.0, 8.0)));
+        t
+    }
+
+    /// A 20 mm block over a 20 x 20 square, the hole's column cut to `cut_z` out to `cut_r`.
+    fn block(cut_r: f64, cut_z: f64) -> Dexel {
+        let mut d = Dexel::block(-10.0, -10.0, 10.0, 10.0, 20.0, 0.25).expect("block");
+        d.cut_chord(Point3::new(0.0, 0.0, cut_z), Point3::new(0.0, 0.0, cut_z), cut_r);
+        d
+    }
+
+    fn refusal(prior: Option<&Dexel>) -> String {
+        judge(&[hole()], &path(), 3.0, prior).err().map(|e| e.to_string()).unwrap_or_default()
+    }
+
+    #[test]
+    fn a_hole_drilled_to_the_minor_diameter_below_the_thread_is_air() {
+        assert!(judge(&[hole()], &path(), 3.0, Some(&block(3.3, 5.0))).is_ok());
+        // Cut exactly to the mill's lowest point is still air.
+        assert!(judge(&[hole()], &path(), 3.0, Some(&block(3.3, 8.0))).is_ok());
+    }
+
+    #[test]
+    fn solid_shallow_or_narrow_stock_under_the_mill_is_refused_by_name() {
+        let solid = refusal(Some(&block(0.0, 20.0)));
+        assert!(solid.contains("the hole at (0.000, 0.000) is not drilled yet") && solid.contains("6.600 mm minor diameter"), "{solid}");
+        let shallow = refusal(Some(&block(3.3, 9.0)));
+        assert!(shallow.contains("stands at z 9.000") && shallow.contains("lowest point at z 8.000"), "{shallow}");
+        // Opened only to the mill's own width: the minor circle (less a cell) still holds stock.
+        assert!(refusal(Some(&block(2.5, 5.0))).contains("not drilled yet"));
+        assert!(refusal(Some(&block(3.0, 5.0))).contains("not drilled yet"));
+    }
+
+    #[test]
+    fn an_unknown_prior_is_refused_never_read_as_air() {
+        let none = refusal(None);
+        assert!(none.contains("nothing ahead of the thread"), "{none}");
+        // A hole off the grid has no reading at all.
+        let mut far = hole();
+        far.xy = Point2::new(50.0, 50.0);
+        let mut p = path();
+        for m in &mut p.moves {
+            m.from.x += 50.0;
+            m.from.y += 50.0;
+            m.to.x += 50.0;
+            m.to.y += 50.0;
+        }
+        let msg = judge(&[far], &p, 3.0, Some(&block(3.3, 5.0))).err().map(|e| e.to_string()).unwrap_or_default();
+        assert!(msg.contains("cannot be judged"), "{msg}");
+    }
+
+    #[test]
+    fn a_hole_the_path_never_enters_is_not_read() {
+        let mut other = hole();
+        other.xy = Point2::new(5.0, 5.0);
+        other.radius = 1.0;
+        assert!(judge(&[other], &path(), 0.5, None).is_ok());
+    }
+}

@@ -0,0 +1,251 @@
+//! The thread-milling operation's app half (#894): the door that judges tool and thread against each other by name, the kernel plan, and the two readings the gouge laws take of a thread mill - its crests against the thread's major circle, its tooth roots against the part.
+//!
+//! Provenance: ISO 724 / ISO 965-1 thread depths and public machine-tool
+//! handbook thread milling, as `camcraft_tools::thread_mill` and
+//! `machining2d::thread_mill` cite them; the door and the verdict
+//! readings are our own design. No vendor material consulted.
+//!
+//! A thread is cut INTO the wall the model shows (CAD draws a tapped
+//! hole at its minor diameter), so the tool's full cylinder against the
+//! part would read every thread as a gouge. The two readings split the
+//! tool where the thread splits it: the tooth crests may reach the
+//! major circle and no further (the tangency law, against
+//! [`crest_region`]), and the body under the teeth may not enter the
+//! part at all (the solid law, with [`root_cutter`]).
+
+use camcraft_tools::thread_mill as form;
+
+use crate::drilling::Hole;
+use crate::geo2d::Region;
+use crate::machining2d::{self, GenError, ThreadHole, ThreadParams};
+use crate::tools::Tool;
+use crate::verify::{Cutter, Warning};
+
+use super::heights::ResolvedHeights;
+use super::material_source::{disk_loop, rim_is};
+use super::types::OpParams;
+
+/// The thread's radial depth for `pitch`, mm: internal threads only in
+/// this slice.
+fn depth_of(pitch: f64) -> f64 {
+    machining2d::THREAD_DEPTH_PER_PITCH * pitch
+}
+
+/// The door (#894): why `tool` cannot cut the thread `params` states, by
+/// name, or `None`. Asked when an operation is created, edited or
+/// re-tooled, and again at generate. `None` for another kind of
+/// operation, for a tool that is no thread mill (the tool law's
+/// family door names that one), and for a single-form mill whose pitch
+/// is not stated yet (the generator names that one).
+#[must_use]
+pub fn door(tool: &Tool, params: &OpParams) -> Option<String> {
+    let OpParams::Thread { pitch, infeed, holes, .. } = params else {
+        return None;
+    };
+    if !form::is_thread_mill(tool.kind) {
+        return None;
+    }
+    if let Some(why) = form::form_refusal(tool) {
+        return Some(why);
+    }
+    let no_air = || {
+        holes.iter().find(|x| tool.diameter * 0.5 >= x.radius).map(|x| {
+            format!(
+                "a {} mm thread mill has no air to enter the {} mm drill hole at ({}, {}) - the mill must be smaller than the thread's minor diameter",
+                tool.diameter,
+                x.radius * 2.0,
+                x.xy.x,
+                x.xy.y
+            )
+        })
+    };
+    let pitch = match form::resolve_pitch(tool, *pitch) {
+        Ok(p) => p,
+        // A single-form mill with the pitch not stated yet is an
+        // unfinished operation, not an impossible one: a new Thread
+        // operation starts that way, and the generator refuses it by
+        // name until the pitch is stated. Everything that needs no
+        // pitch is still judged here.
+        Err(_) if pitch.is_none() => return no_air(),
+        Err(why) => return Some(why),
+    };
+    let h = depth_of(pitch);
+    if tool.diameter * 0.5 <= h {
+        return Some(format!(
+            "a {} mm thread mill is no wider than twice the {h} mm thread depth of a {pitch} mm pitch - its teeth leave no core",
+            tool.diameter
+        ));
+    }
+    if *infeed > h + 1e-9 {
+        return Some(format!(
+            "the radial infeed of {infeed} mm is more than the {h} mm thread depth a {pitch} mm pitch stands at"
+        ));
+    }
+    no_air()
+}
+
+/// The kernel's parameters for this operation and tool, heights
+/// resolved; every door refusal is the generator's refusal too.
+pub(super) fn kernel_params(tool: &Tool, params: &OpParams, hl: &ResolvedHeights) -> Result<ThreadParams, GenError> {
+    let OpParams::Thread { infeed, feed, plunge_feed, climb, holes, pitch, hand, .. } = params else {
+        return Err(GenError::Invalid("not a thread-milling operation".into()));
+    };
+    if !form::is_thread_mill(tool.kind) {
+        return Err(GenError::Invalid(format!(
+            "thread milling needs a thread mill or a single-form thread mill - this tool is a {}",
+            tool.kind
+        )));
+    }
+    // The pitch first: an unstated one on a single-form mill passes the
+    // door (an unfinished operation) and is refused here, by name.
+    let pitch = form::resolve_pitch(tool, *pitch).map_err(GenError::Invalid)?;
+    if let Some(why) = door(tool, params) {
+        return Err(GenError::Invalid(why));
+    }
+    Ok(ThreadParams {
+        holes: holes
+            .iter()
+            .map(|x| ThreadHole {
+                xy: x.xy,
+                radius: x.radius,
+                top_z: x.entry_z,
+                floor_z: hl.bottom.unwrap_or(x.floor_z),
+                stepped: x.stepped,
+                // A stated bottom is the author's own floor; only the
+                // hole's own exit takes the run-through allowance.
+                through: x.through && hl.bottom.is_none(),
+            })
+            .collect(),
+        pitch,
+        tool_diameter: tool.diameter,
+        rows: form::rows(tool),
+        infeed: *infeed,
+        external: false,
+        hand: *hand,
+        climb: *climb,
+        clearance_z: hl.clearance,
+        retract_z: hl.retract,
+        feed: *feed,
+        plunge_feed: *plunge_feed,
+    })
+}
+
+/// The crest law's region: `region` with each threaded hole's rim moved
+/// out from the minor circle to the major one (`depth` further), so the
+/// tangency verdict convicts a tooth crest that passes the thread's own
+/// major diameter and nothing short of it.
+pub(super) fn crest_region(region: Region, holes: &[Hole], depth: f64) -> Result<Region, GenError> {
+    if holes.is_empty() {
+        return Ok(region);
+    }
+    let mut loops: Vec<_> = region.loops().iter().filter(|l| !holes.iter().any(|x| rim_is(l, *x))).cloned().collect();
+    for x in holes {
+        loops.push(disk_loop(x.xy, x.radius + depth)?);
+    }
+    Ok(Region::new(loops)?)
+}
+
+/// The root law's cutter: `cutter` narrowed by the thread depth for a
+/// Thread operation, so the solid law holds the body under the teeth
+/// out of the part - radially at the minor wall, and at the tip with no
+/// allowance at all. Every other operation, and a tool whose pitch does
+/// not resolve (refused before any path exists), keeps its cutter.
+#[must_use]
+pub(super) fn root_cutter(cutter: Cutter, tool: &Tool, params: &OpParams) -> Cutter {
+    let OpParams::Thread { pitch, .. } = params else {
+        return cutter;
+    };
+    match form::resolve_pitch(tool, *pitch) {
+        Ok(p) if cutter.radius > depth_of(p) => Cutter { radius: cutter.radius - depth_of(p), ..cutter },
+        _ => cutter,
+    }
+}
+
+/// The crossing law stands down for a Thread operation: every radial
